fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let len = numbers.len();
    if len == 0 {
        return Vec::new();
    }

    // Result length is 2 * len - 1
    let mut res = Vec::with_capacity(2 * len - 1);

    for (i, &num) in numbers.iter().enumerate() {
        if i > 0 {
            res.push(delim);
        }
        res.push(num);
    }

    res
}